package ru.mtproxy.picker;
import android.app.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import io.nayuki.qrcodegen.QrCode;
final class QrDialog {
 static final String APP_URL="https://github.com/riehnh/mtpoxy-panel/raw/refs/heads/main/downloads/MTPoxy.apk";
 static void show(Activity activity,String title,String payload){try{QrCode code=QrCode.encodeText(payload,QrCode.Ecc.MEDIUM);LinearLayout content=new LinearLayout(activity);content.setOrientation(1);int padding=(int)(16*activity.getResources().getDisplayMetrics().density);content.setPadding(padding,padding,padding,padding);View image=new View(activity){final Paint paint=new Paint();@Override protected void onDraw(Canvas canvas){canvas.drawColor(Color.WHITE);int full=code.size+8,scale=Math.max(1,Math.min(getWidth(),getHeight())/full),left=(getWidth()-full*scale)/2,top=(getHeight()-full*scale)/2;paint.setColor(Color.BLACK);for(int y=0;y<code.size;y++)for(int x=0;x<code.size;x++)if(code.getModule(x,y))canvas.drawRect(left+(x+4)*scale,top+(y+4)*scale,left+(x+5)*scale,top+(y+5)*scale,paint);}};image.setContentDescription("QR-код ссылки");content.addView(image,new LinearLayout.LayoutParams(-1,(int)(300*activity.getResources().getDisplayMetrics().density)));TextView help=new TextView(activity);help.setText("Наведите камеру другого телефона на код.");help.setPadding(0,padding,0,0);content.addView(help);new AlertDialog.Builder(activity).setTitle(title).setView(content).setPositiveButton("Готово",null).setNeutralButton("Скопировать ссылку",(d,w)->((ClipboardManager)activity.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText(title,payload))).show();}catch(Exception error){Toast.makeText(activity,"Не удалось создать QR-код: слишком длинная ссылка",Toast.LENGTH_LONG).show();}}
}
